if($me['role']==='admin'){$tabs['auditoria']='Auditoría';if(!mpi_sso_enabled())$tabs['usuarios']='Usuarios y roles';}
$tab=(string)($_GET['tab']??'inicio');if(!isset($tabs[$tab]))$tab='inicio';
if($_SERVER['REQUEST_METHOD']==='POST'){
 mpi_check_csrf();require dirname(__DIR__).'/private/panel_actions.php';
 try{$notice=['type'=>'success','message'=>mpi_handle_action($me)];}
 catch(Throwable $e){error_log('MPI admin save: '.$e->getMessage());$notice=['type'=>'error','message'=>$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo guardar. Verifica permisos de base de datos e imágenes.'];}
 $_SESSION['flash']=$notice;
 $dest=(string)($_POST['tab']??$tab);if(!isset($tabs[$dest]))$dest='inicio';$pg=max(1,min(100000,(int)($_POST['page']??1)));mpi_redirect('panel.php?tab='.rawurlencode($dest).(in_array($dest,['productos','proformas'],true)?'&page='.$pg:''));
}
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
$pdo=mpi_db();$categories=$pdo->query('SELECT * FROM categories ORDER BY sort_order,id')->fetchAll();
$products=[];$quotes=[];$users=[];$events=[];
$productPage=max(1,min(100000,(int)($_GET['page']??1)));$productTotal=0;$quoteTotal=0;$quotePage=$productPage;
if($tab==='productos'){$productTotal=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$productPage=min($productPage,max(1,(int)ceil($productTotal/50)));$q=$pdo->prepare('SELECT p.*,c.name AS category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC LIMIT 50 OFFSET ?');$q->bindValue(1,($productPage-1)*50,PDO::PARAM_INT);$q->execute();$products=$q->fetchAll();}
if($tab==='proformas'){$quoteTotal=(int)$pdo->query('SELECT COUNT(*) FROM quotes')->fetchColumn();$quotePage=min($quotePage,max(1,(int)ceil($quoteTotal/50)));$q=$pdo->prepare('SELECT * FROM quotes ORDER BY id DESC LIMIT 50 OFFSET ?');$q->bindValue(1,($quotePage-1)*50,PDO::PARAM_INT);$q->execute();$quotes=$q->fetchAll();}
if($tab==='usuarios')$users=$pdo->query('SELECT id,username,display_name,role,active,created_at FROM users ORDER BY id')->fetchAll();
if($tab==='auditoria')$events=$pdo->query('SELECT a.*,u.username FROM audit_events a LEFT JOIN users u ON a.user_id=u.id ORDER BY a.id DESC LIMIT 90')->fetchAll();
function field(string $label,string $name,string $value='',string $type='text',string $other=''):void{
 echo '<label>'.mpi_e($label).'<input name="'.mpi_e($name).'" type="'.mpi_e($type).'" value="'.mpi_e($value).'" '.$other.'></label>';
}
function textArea(string $label,string $name,string $value='',int $max=2500):void{echo '<label class="full">'.mpi_e($label).'<textarea name="'.mpi_e($name).'" maxlength="'.$max.'" rows="3">'.mpi_e($value).'</textarea></label>';}
function imageFile(string $field,string $path=''):void{
 if(mpi_image($path))echo '<div class="full"><img class="panel-image-thumb" src="'.mpi_e(mpi_image($path)).'" alt="Imagen actual"></div>';
 echo '<label>Imagen JPG/PNG/WebP (hasta 5 MB)<input type="file" name="'.mpi_e($field).'" accept="image/jpeg,image/png,image/webp"></label>';
 echo '<label><input type="checkbox" name="clear_image" value="1"> Quitar imagen actual</label>';
}
function csrfTag(string $tab,string $action):void{global $productPage,$quotePage;echo '<input type="hidden" name="_csrf" value="'.mpi_e(mpi_csrf()).'"><input type="hidden" name="tab" value="'.mpi_e($tab).'"><input type="hidden" name="action" value="'.mpi_e($action).'">';if($tab==='productos'||$tab==='proformas')echo '<input type="hidden" name="page" value="'.(int)($tab==='productos'?$productPage:$quotePage).'">';}
function categoryForm(array $cat):void{ $isNew=!isset($cat['id']);?>
<form method="post" enctype="multipart/form-data" class="panel-form"><?php csrfTag('categorias','category_save');?><input type="hidden" name="id" value="<?=(int)($cat['id']??0)?>">
<?php field('Nombre','name',(string)($cat['name']??''),'text','required maxlength="120"');field('Orden','sort_order',(string)($cat['sort_order']??0),'number','min="0" max="100000"');textArea('Descripción','description',(string)($cat['description']??''),1000);?>
<?php if(!empty($cat['image_path'])&&mpi_image($cat['image_path'])):?><div class="full"><img class="panel-image-thumb" src="<?=mpi_e(mpi_image($cat['image_path']))?>" alt="Imagen de la categoría"></div><?php endif;?><label>Imagen de categoría<input type="file" name="category_image" accept="image/jpeg,image/png,image/webp"></label><label><input type="checkbox" name="clear_image" value="1"> Quitar imagen</label>
<label><input type="checkbox" name="visible" value="1" <?=!$isNew&&empty($cat['visible'])?'':'checked'?>> Visible al público</label><div><button class="btn gold" type="submit"><?=$isNew?'Crear categoría':'Guardar categoría'?></button></div></form>
<?php }
function productForm(array $p,array $categories):void{$new=!isset($p['id']);$variants=json_decode($p['variants_json']??'[]',true)?:[];$lines=implode("\n",array_map(static fn($v)=>($v['label']??'').' | '.number_format((float)($v['price']??0),4,'.',''),$variants));?>
<form method="post" enctype="multipart/form-data" class="panel-form"><?php csrfTag('productos','product_save');?><input type="hidden" name="id" value="<?=(int)($p['id']??0)?>">
<label>Categoría<select name="category_id" required><?php foreach($categories as $cat):?><option value="<?=(int)$cat['id']?>" <?=(int)($p['category_id']??0)===(int)$cat['id']?'selected':''?>><?=mpi_e($cat['name'])?></option><?php endforeach;?></select></label>
<?php field('Nombre del producto','name',(string)($p['name']??''),'text','required maxlength="180"');field('Código / SKU','sku',(string)($p['sku']??''),'text','maxlength="80"');field('Precio base en USD (0 = consultar)','base_price',(string)($p['base_price']??'0.0000'),'text','required inputmode="decimal" pattern="[0-9]+(\\.[0-9]{1,4})?"');field('Unidad de venta','unit',(string)($p['unit']??'unidad'),'text','required maxlength="30"');field('Orden','sort_order',(string)($p['sort_order']??0),'number','min="0" max="100000"');textArea('Descripción comercial / ficha técnica','description',(string)($p['description']??''),2500);textArea('Presentaciones: una por línea, formato  Medida / Color / Espesor | Precio USD','variants_lines',$lines,4000);?>
<p class="form-hint full">Ejemplo: 5.80 m · Blanco · 2.5 mm | 18.5000. Usa 0 para precio por cotizar. Si no ingresas variantes, se utiliza el precio base.</p>
<?php if(!empty($p['image_path'])&&mpi_image($p['image_path'])):?><div class="full"><img class="panel-image-thumb" src="<?=mpi_e(mpi_image($p['image_path']))?>" alt="Imagen actual"></div><?php endif;?>
<label>Foto del producto<input type="file" name="product_image" accept="image/jpeg,image/png,image/webp"></label><label><input type="checkbox" name="clear_image" value="1"> Quitar foto</label>
<label><input type="checkbox" name="visible" value="1" <?=$new||!empty($p['visible'])?'checked':''?>> Publicar en el catálogo</label><label><input type="checkbox" name="featured" value="1" <?=!empty($p['featured'])?'checked':''?>> Destacado</label>
<div><button class="btn gold" type="submit"><?=$new?'Agregar producto':'Guardar cambios'?></button></div></form>
<?php }
?>
